(* [comment removed for export] *)
Record fzw := mkFZW {
  w_p1 : bptr ; w_allocb : Z ; w_p2 : bptr ; w_regb : Z ; w_p3 : bptr ; w_cfgb : Z ; w_p4 : bptr ; w_schedb : Z ;
  w_p5 : bptr ; w_v : Z ; w_p6 : bptr ; w_q : Z ; w_p7 : bptr ; w_stb : Z ; w_p8 : bptr ; w_va : Z ; w_p9 : bptr ; w_A : Z }.

Definition fz_LB2 (N : Z) (W : fzw) (LB : list block) : list block :=
  st_LB N (w_p9 W) (w_A W)
    (mi_LB (w_p5 W) (w_v W) (w_p6 W) (w_q W) (w_p7 W) (w_stb W) (w_p8 W) (w_va W)
       (fz_LB1 (w_p1 W) (w_allocb W) (w_p2 W) (w_regb W) (w_p3 W) (w_cfgb W) (w_p4 W) (w_schedb W) LB)).

(* [comment removed for export] *)
Definition fz_NEW2 (N : Z) (W : fzw) : list block :=
